<?php

namespace App\Console\Commands;

use App\Models\User;
use Illuminate\Console\Command;

class CheckSmkN5Pplg extends Command
{
    protected $signature = 'check:smkn5-pplg';

    protected $description = 'Bandingkan roster PPLG SMK N 5 Surakarta terhadap akun yang ada di database';

    private const ROSTER_B64 = '';

    public function handle(): int
    {
        $roster = json_decode(base64_decode(self::ROSTER_B64), true);

        $normalize = fn (string $s) => strtolower(trim(preg_replace('/\s+/', ' ', $s)));

        $ok = [];
        $collision = [];
        $missing = [];

        foreach ($roster as $r) {
            $wantName = $normalize($r['nama']);
            $email = strtolower($r['email']);

            $byEmail = User::where('email', $email)->first();

            if ($byEmail && $normalize($byEmail->name) === $wantName) {
                $ok[] = $r['nama'];
                continue;
            }

            $byName = User::whereRaw('LOWER(TRIM(name)) = ?', [$wantName])->first();

            if ($byName) {
                $collision[] = [
                    'roster_nama' => $r['nama'],
                    'roster_email' => $email,
                    'found_id' => $byName->id,
                    'found_email' => $byName->email,
                    'found_school' => $byName->school,
                    'note' => 'nama ditemukan tapi di email/sekolah berbeda dari yang diharapkan',
                ];
            } elseif ($byEmail) {
                $collision[] = [
                    'roster_nama' => $r['nama'],
                    'roster_email' => $email,
                    'found_id' => $byEmail->id,
                    'found_name' => $byEmail->name,
                    'found_school' => $byEmail->school,
                    'note' => 'email sudah dipakai siswa lain (overwrite)',
                ];
            } else {
                $missing[] = [
                    'roster_nama' => $r['nama'],
                    'roster_email' => $email,
                ];
            }
        }

        $result = [
            'total_roster' => count($roster),
            'ok_count' => count($ok),
            'collision_count' => count($collision),
            'missing_count' => count($missing),
            'collision' => $collision,
            'missing' => $missing,
        ];

        file_put_contents(
            storage_path('app/smkn5_pplg_check_result.json'),
            json_encode($result, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)
        );

        $this->info('OK: '.count($ok).' | Collision: '.count($collision).' | Missing: '.count($missing));

        return self::SUCCESS;
    }
}
